NUM_EN = 'zero one two three four five six seven eight nine ten eleven twelve thirteen'.split()
NUM_TL = 'sero isa dalawa tatlo apat lima anim pito walo siyam sampu labing-isa labindalawa labintatlo'.split()
TENS_EN = {20: 'twenty', 30: 'thirty', 40: 'forty', 50: 'fifty', 60: 'sixty', 70: 'seventy', 80: 'eighty', 90: 'ninety', 100: 'hundred', 1000: 'thousand'}
TENS_TL = {20: 'dalawampu', 30: 'tatlumpu', 40: 'apatnapu', 50: 'limampu', 60: 'animnapu', 70: 'pitumpu', 80: 'walumpu', 90: 'siyamnapu', 100: 'sandaan', 1000: 'sanlibo'}
for n in range(14):
    V[de(n)] = (None, f'{NUM_EN[n]} ({n})', f'{NUM_TL[n]} ({n})')
for n in TENS_EN:
    V['tausend' if n == 1000 else de(n)] = (None, f'{TENS_EN[n]} ({n})', f'{TENS_TL[n]} ({n})')

vocab = []
for lemma, wid in A102.items():
    art, en, tl = V[lemma]
    v = {'id': wid, 'lemma': lemma, 'en': en, 'tl': tl}
    if art:
        v['article'] = art
    vocab.append(v)

C = lambda phrase, de_, en, tl: {'phrase': phrase, 'note': L(de_, en, tl)}
# Content standard v2 §1 (docs/content-standard.md): phrase / rule (+ speakable examples) / culture cards, lesson intro.
PHRASE = lambda phrase, de_, en, tl: {'kind': 'phrase', 'phrase': phrase, 'note': L(de_, en, tl)}
RULE = lambda phrase, de_, en, tl, examples: {'kind': 'rule', 'phrase': phrase, 'note': L(de_, en, tl), 'examples': examples}
CULTURE = lambda phrase, de_, en, tl: {'kind': 'culture', 'phrase': phrase, 'note': L(de_, en, tl)}
INTRO = lambda situation, goal: {'situation': situation, 'goal': goal}
lessons = []


def lesson(n, title, introduces, cards, items, intro=None):
    lid = f'{CH}-L{n:02d}'
    out = []
    for k, it in enumerate(items, 1):
        it['id'] = f'{lid}-I{k}'
        out.append(it)
    lessons.append({'id': lid, 'title': title, **({'intro': intro} if intro else {}), 'introduces': [r for r in R(*introduces) if r not in NO_CARD], 'cards': cards, 'items': out})


