WHICH_WORD = L('Hören Sie. Jemand buchstabiert. Welches Wort ist das?', 'Listen. Someone spells. Which word is it?', 'Makinig. May nag-i-spell. Anong salita ito?')


# Content standard v2 (docs/content-standard.md): intro + 3–6 cards + 6–8 items per lesson, one picture task each.
SOUND = lambda s: s  # audio text for letters: lower case, no full stop (see spell_audio)
LOOK_AT = lambda de_, en, tl: L(de_, en, tl)

