# content standard v2 checks
for l in lessons:
    its = l['items']
    assert l.get('intro') and 3 <= len(l['cards']) <= 6 and 6 <= len(its) <= 8, (l['id'], len(l['cards']), len(its))
    assert any('image' in i for i in its) and any(i['type'] == 'cloze' and (i.get('bank') or any(g.get('hint') for g in i['gaps'].values())) for i in its), l['id']
    assert len({i['skill'] for i in its}) >= 2, l['id']
    for i in its:
        if i['type'] == 'choice':
            assert len(set(i['options'])) == len(i['options']) >= 3 and i['instruction']['de'], i['id']
        if i['type'] == 'cloze':
            assert len(i['gaps']) <= 3 and ('bank' in i or any('hint' in g for g in i['gaps'].values())), i['id']
            if 'bank' in i:
                assert all(g['accept'][0] in i['bank'] for g in i['gaps'].values()), i['id']
                assert len(i['bank']) - len(i['gaps']) in (1, 2), i['id']

# every vocab id introduced, except the number set (see spec-gaps G-014)
introduced = {r for l in lessons for r in l['introduces']}
missing = [v['lemma'] for v in vocab if v['id'] not in introduced and v['id'] not in NO_CARD]
print('not introduced:', missing)

out = {'schemaVersion': 1, 'chapterId': CH, 'tlReviewStatus': 'machine', 'vocab': vocab, 'lessons': lessons}
json.dump(out, open(f'{ROOT}/src/lib/content/a1-02.json', 'w'), ensure_ascii=False, indent='\t')
print(len(lessons), 'lessons', sum(len(l['items']) for l in lessons), 'items')
